/*
 * The PlayStation MDEC decoder (T37), standalone: no PsyQ, no PsyCross, no
 * libpress. The header (host_mdec.h) has the contract; this file is the
 * implementation and the notes on the two formats it walks.
 *
 * The VLC side is MPEG-1's DCT coefficient table, ISO/IEC 11172-2 Table B.14
 * (public), plus the escape and end-of-block codes. The table below is stored
 * as (code, bits, symbol) triples and compiled into a binary tree once, so no
 * generated byte table is committed and the source states what it knows.
 *
 * The run-level side is the PSX's own layout: a 32-bit command word, then
 * 16-bit tokens whose high 6 bits are the run and whose low 10 bits are the
 * level in two's complement. A macroblock is Cr, Cb, Y1, Y2, Y3, Y4, and the
 * macroblocks themselves go down each column before the next column.
 *
 * Everything is arithmetic on public constants or computed from a formula:
 * no retail or Sony bytes (ADR-001).
 */
#include "host_mdec.h"

#include <math.h>
#include <string.h>

/* Symbol kinds in the table below. */
#define HMDEC_VLC_AC 0
#define HMDEC_VLC_ESCAPE 1
#define HMDEC_VLC_EOB 2

typedef struct {
    uint16_t code; /* right-aligned, MSB first */
    uint8_t bits;
    uint8_t kind;
    int8_t run;
    int16_t level;
} HmSymbol;

