/*
 * The intra quantization matrix, in zigzag order (public: MPEG-1's intra
 * matrix as the PSX uses it, qt[0] = 2). Both of the decoder's tables are the
 * same matrix; the format keeps two because the MDEC has two.
 */
static const uint8_t hmIntraQuant[64] = {
    0x02, 0x10, 0x10, 0x13, 0x10, 0x13, 0x16, 0x16,
    0x16, 0x16, 0x16, 0x16, 0x1A, 0x18, 0x1A, 0x1B,
    0x1B, 0x1B, 0x1A, 0x1A, 0x1A, 0x1A, 0x1B, 0x1B,
    0x1B, 0x1D, 0x1D, 0x1D, 0x22, 0x22, 0x22, 0x1D,
    0x1D, 0x1D, 0x1B, 0x1B, 0x1D, 0x1D, 0x20, 0x20,
    0x22, 0x22, 0x25, 0x26, 0x25, 0x23, 0x23, 0x22,
    0x23, 0x26, 0x26, 0x28, 0x28, 0x28, 0x30, 0x30,
    0x2E, 0x2E, 0x38, 0x38, 0x3A, 0x45, 0x45, 0x53
};

/*
 * zigzag[k] = natural (row-major) index of the k-th coefficient in the
 * stream. MPEG-1's zigzag is public; this is its zigzag-to-natural direction,
 * the one a decoder needs when its IDCT reads a natural-order block. (The
 * inverse table is the common "natural -> zigzag" listing; using that one
 * here silently shuffles the AC coefficients and lifts high-frequency noise.)
 */
static const uint8_t hmZigzag[64] = {
     0,  1,  8, 16,  9,  2,  3, 10,
    17, 24, 32, 25, 18, 11,  4,  5,
    12, 19, 26, 33, 40, 48, 41, 34,
    27, 20, 13,  6,  7, 14, 21, 28,
    35, 42, 49, 56, 57, 50, 43, 36,
    29, 22, 15, 23, 30, 37, 44, 51,
    58, 59, 52, 45, 38, 31, 39, 46,
    53, 60, 61, 54, 47, 55, 62, 63
};

static unsigned hmRead16(const uint8_t *p) {
    return (unsigned)p[0] | ((unsigned)p[1] << 8);
}

static unsigned long hmRead32(const uint8_t *p) {
    return (unsigned long)p[0] | ((unsigned long)p[1] << 8) |
           ((unsigned long)p[2] << 16) | ((unsigned long)p[3] << 24);
}

static void hmWrite16(uint8_t *p, unsigned v) {
    p[0] = (uint8_t)v;
    p[1] = (uint8_t)(v >> 8);
}

static void hmWrite32(uint8_t *p, unsigned long v) {
    p[0] = (uint8_t)v;
    p[1] = (uint8_t)(v >> 8);
    p[2] = (uint8_t)(v >> 16);
    p[3] = (uint8_t)(v >> 24);
}

/* A 10-bit level: two's complement, as the run-level stream carries it. */
static int hmSigned10(int v) {
    return (v >= 512) ? v - 1024 : v;
}

void hostMdecVlcBuild(HostMdecVlcTable *table) {
    int i;

    table->nodes = 1;
    table->child[0][0] = -1;
    table->child[0][1] = -1;
    table->symbol[0] = -1;
    table->lastErrorBit = -1;
    table->lastTokens = 0;

    for (i = 0; i < HMDEC_VLC_SYMBOLS; i++) {
        int node = 0;
        int bit;
        const HmSymbol *sym = hmSymbols + i;

        for (bit = sym->bits - 1; bit >= 0; bit--) {
            int branch = (sym->code >> bit) & 1;
            int next = table->child[node][branch];

            if (next < 0) {
                if (table->nodes >= HMDEC_VLC_MAX_NODES) {
                    return; /* cannot happen with Table B.14 (113 codes) */
                }
                next = table->nodes++;
                table->child[next][0] = -1;
                table->child[next][1] = -1;
                table->symbol[next] = -1;
                table->child[node][branch] = (int16_t)next;
            }
            node = next;
        }
        table->symbol[node] = (int16_t)i;
    }
}

/* The Huffman bit stream: little-endian 16-bit words, MSB first inside each. */
typedef struct {
    const uint8_t *data;
    long pos;
} HmBits;

static int hmBit(HmBits *bits) {
    long word = bits->pos >> 4;
    int sub = (int)(bits->pos & 15);
    unsigned v = hmRead16(bits->data + word * 2);

    bits->pos++;
    return (int)((v >> (15 - sub)) & 1u);
}

static int hmBits(HmBits *bits, int n) {
    int v = 0;

    while (n-- > 0) {
        v = (v << 1) | hmBit(bits);
    }
    return v;
}

/* One AC symbol; returns its index into hmSymbols, or -1 for an invalid code. */
static int hmVlc(HostMdecVlcTable *table, HmBits *bits) {
    int node = 0;
    int len = 0;

    while (table->symbol[node] < 0) {
        int branch = hmBit(bits);

        node = table->child[node][branch];
        len++;
        if (node < 0 || len > 16) {
            table->lastErrorBit = (int)bits->pos;
            return -1;
        }
    }
    return table->symbol[node];
}

/*
 * Decodes one frame's Huffman data into the run-level stream. The stream is
 * `count` 32-bit words after the command word, i.e. 2*count tokens, and every
 * unused token is the 0xFE00 end code. The frame terminator is read as ten
 * raw bits before each block's DC: 0x1FF for the version-2 streams the EU
 * discs' movies use, 0x3FF for version 3 (the value libpress's own decoder
 * compares). Version 3's DC coding is the (size VLC, difference) pair, which
 * this decoder does not implement yet: it is only reached by version-2 data
 * here, as the harness's assertions show.
 */
int hostMdecVlc2(const void *src, void *dst, void *table) {
    const uint8_t *in = (const uint8_t *)src;
    uint8_t *out = (uint8_t *)dst;
    HostMdecVlcTable *vlc = (HostMdecVlcTable *)table;
    unsigned count = hmRead16(in + 0);
    unsigned quant = hmRead16(in + 4) & 0x3Fu;
    unsigned version = hmRead16(in + 6);
    unsigned terminator = (version == 3) ? 0x3FFu : 0x1FFu;
    unsigned limit = count * 2u;
    unsigned used = 0;
    HmBits bits;

    bits.data = in + 8;
    bits.pos = 0;
    vlc->lastErrorBit = -1;
    vlc->lastTokens = 0;

    /* The command word: 0x38000000 selects 24-bit output, and count is the
       number of 32-bit words of run-level data that follow it. */
    hmWrite32(out, 0x38000000ul | (unsigned long)(count & 0xFFFFu));

    while (used < limit) {
        int dc = hmBits(&bits, 10);

        if (dc == (int)terminator) {
            break;
        }
        hmWrite16(out + 4 + used * 2, (quant << 10) | ((unsigned)dc & 0x3FFu));
        used++;

        for (;;) {
            int index = hmVlc(vlc, &bits);
            int run;
            int level;

            if (index < 0) {
                vlc->lastTokens = (int)used;
                return 1;
            }
            if (hmSymbols[index].kind == HMDEC_VLC_EOB) {
                if (used < limit) {
                    hmWrite16(out + 4 + used * 2, 0xFE00);
                    used++;
                }
                break;
            }
            if (hmSymbols[index].kind == HMDEC_VLC_ESCAPE) {
                run = hmBits(&bits, 6);
                level = hmSigned10(hmBits(&bits, 10));
            } else {
                run = hmSymbols[index].run;
                level = hmSymbols[index].level;
                if (hmBit(&bits)) {
                    level = -level;
                }
            }
            if (used >= limit) {
                break;
            }
            hmWrite16(out + 4 + used * 2,
                      ((unsigned)run << 10) | ((unsigned)level & 0x3FFu));
            used++;
            if (used >= limit) {
                break;
            }
        }
    }

    vlc->lastTokens = (int)used;
    while (used < limit) {
        hmWrite16(out + 4 + used * 2, 0xFE00);
        used++;
    }
    return 0;
}

void hostMdecInit(HostMdec *mdec) {
    int u;
    int x;

    hostMdecVlcBuild(&mdec->vlc);
    memcpy(mdec->qt[0], hmIntraQuant, sizeof(hmIntraQuant));
    memcpy(mdec->qt[1], hmIntraQuant, sizeof(hmIntraQuant));

    /* scale[u*8+x] = 32768 * C(u) * cos((2x+1)*u*PI/16), C(0)=1/sqrt(2) */
    for (u = 0; u < 8; u++) {
        double cu = (u == 0) ? 0.70710678118654752440 : 1.0;

        for (x = 0; x < 8; x++) {
            double angle = (double)((2 * x + 1) * u) * 3.14159265358979323846 / 16.0;

            mdec->scale[u * 8 + x] = (int16_t)(32768.0 * cu * cos(angle));
        }
    }
}

/* dst[y*8+x] = sum_z src[z*8+y] * scale[z*8+x], rounded; two passes. */
static void hmIdct(const HostMdec *mdec, const int *block, int *out) {
    int src[64];
    int dst[64];
    int pass;

    memcpy(src, block, sizeof(src));
    for (pass = 0; pass < 2; pass++) {
        int x;
        int y;

        for (x = 0; x < 8; x++) {
            for (y = 0; y < 8; y++) {
                int sum = 0;
                int z;

                for (z = 0; z < 8; z++) {
                    sum += src[z * 8 + y] * mdec->scale[z * 8 + x];
                }
                dst[y * 8 + x] = (sum + 0x8000) >> 16;
            }
        }
        memcpy(src, dst, sizeof(src));
    }
    memcpy(out, src, sizeof(src));
}

/* YUV -> RGB, the fixed point the MDEC's own output implies. */
static int hmClamp(int v) {
    if (v < -128) {
        return 0;
    }
    if (v > 127) {
        return 255;
    }
    return v + 128;
}

static void hmYuv(int y, int cr, int cb, int *r, int *g, int *b) {
    *r = hmClamp(y + ((91881 * cr) >> 16));
    *g = hmClamp(y - ((22554 * cb + 46802 * cr) >> 16));
    *b = hmClamp(y + ((116130 * cb) >> 16));
}

/*
 * The run-level block reader: the token at `*at` is the DC token (high 6 bits
 * are q_scale, low 10 the signed DC); AC tokens follow until a run carries the
 * position past coefficient 63, which is what 0xFE00's run of 63 does. Returns
 * 1 when the block was closed by 0xFE00, 0 when the stream ran out first.
 */
static int hmBlock(const uint8_t *tokens, int count, int *at,
                   const uint8_t *quant, int *block, int *truncated) {
    int n;
    int q;
    int val;
    int k = 0;

    memset(block, 0, 64 * sizeof(int));
    while (*at < count && hmRead16(tokens + *at * 2) == 0xFE00) {
        (*at)++;
    }
    if (*at >= count) {
        *truncated = 1;
        return 0;
    }

    n = (int)hmRead16(tokens + *at * 2);
    q = (n >> 10) & 0x3F;
    val = hmSigned10(n & 0x3FF) * quant[0];

    for (;;) {
        if (q == 0) {
            val = hmSigned10(n & 0x3FF) * 2;
        }
        if (val < -0x400) {
            val = -0x400;
        }
        if (val > 0x3FF) {
            val = 0x3FF;
        }
        if (q > 0) {
            block[hmZigzag[k]] = val;
        } else {
            block[k] = val;
        }
        (*at)++;
        if (*at >= count) {
            *truncated = 1;
            return 0;
        }
        n = (int)hmRead16(tokens + *at * 2);
        k += ((n >> 10) & 0x3F) + 1;
        if (k > 63) {
            if (n == 0xFE00) {
                (*at)++;
                return 1;
            }
            return 0;
        }
        val = hmSigned10(n & 0x3FF) * quant[k] * q;
        val = (val >= 0) ? (val + 4) / 8 : -((-val + 4) / 8);
    }
}

int hostMdecDecodeFrame(HostMdec *mdec, const void *stream, int width,
                        int height, int depth, void *out, HostMdecStats *stats) {
    const uint8_t *data = (const uint8_t *)stream;
    const uint8_t *tokens;
    unsigned long command;
    int count;
    int at = 0;
    int mbw;
    int mbh;
    int m;
    int pixelBytes;

    if (mdec == NULL || stream == NULL || out == NULL) {
        return -1;
    }
    if (width <= 0 || height <= 0 || (width & 15) != 0 || (height & 15) != 0) {
        return -1;
    }

    command = hmRead32(data);
    count = (int)(command & 0xFFFFul);
    tokens = data + 4;

    if (depth == HMDEC_DEPTH_COMMAND) {
        int d = (int)((command >> 26) & 3ul);

        if (d == 2) {
            depth = HMDEC_DEPTH_24BPP;
        } else if (d == 3) {
            depth = HMDEC_DEPTH_15BPP;
        } else {
            return -1;
        }
    }
    if (depth != HMDEC_DEPTH_24BPP && depth != HMDEC_DEPTH_15BPP) {
        return -1;
    }
    pixelBytes = (depth == HMDEC_DEPTH_24BPP) ? 3 : 2;

    if (stats != NULL) {
        memset(stats, 0, sizeof(*stats));
        stats->tokens = count * 2;
    }

    mbw = width / 16;
    mbh = height / 16;

    for (m = 0; m < mbw * mbh; m++) {
        int blocks[6][64];
        int col;
        int row;
        int ox;
        int oy;
        int b;

        /* Cr, Cb, Y1, Y2, Y3, Y4 */
        for (b = 0; b < 6; b++) {
            int truncated = 0;
            int closed;

            closed = hmBlock(tokens, count * 2, &at, mdec->qt[b < 2 ? 1 : 0],
                             blocks[b], &truncated);
            if (truncated) {
                if (stats != NULL) {
                    stats->errors++;
                }
            }
            if (closed) {
                if (stats != NULL) {
                    stats->eobBlocks++;
                }
            } else if (!truncated) {
                if (stats != NULL) {
                    stats->errors++;
                }
            }
            if (stats != NULL) {
                stats->blocks++;
            }
            hmIdct(mdec, blocks[b], blocks[b]);
        }

        /* Column-major macroblock order: m = col * mbh + row */
        col = m / mbh;
        row = m % mbh;
        ox = col * 16;
        oy = row * 16;

        {
            int yy;

            for (yy = 0; yy < 16; yy++) {
                int xx;

                for (xx = 0; xx < 16; xx++) {
                    const int *yb = blocks[(yy < 8) ? ((xx < 8) ? 2 : 3)
                                                   : ((xx < 8) ? 4 : 5)];
                    int y = yb[(yy & 7) * 8 + (xx & 7)];
                    int cr = blocks[0][(yy / 2) * 8 + (xx / 2)];
                    int cb = blocks[1][(yy / 2) * 8 + (xx / 2)];
                    int r;
                    int g;
                    int bl;
                    long o = ((long)(oy + yy) * width + (ox + xx)) * pixelBytes;

                    hmYuv(y, cr, cb, &r, &g, &bl);
                    if (pixelBytes == 3) {
                        uint8_t *p = (uint8_t *)out + o;

                        p[0] = (uint8_t)r;
                        p[1] = (uint8_t)g;
                        p[2] = (uint8_t)bl;
                    } else {
                        uint8_t *p = (uint8_t *)out + o;
                        unsigned v = (unsigned)((bl >> 3) & 0x1F) |
                                     ((unsigned)((g >> 3) & 0x1F) << 5) |
                                     ((unsigned)((r >> 3) & 0x1F) << 10);

                        p[0] = (uint8_t)v;
                        p[1] = (uint8_t)(v >> 8);
                    }
                }
            }
        }
    }

    if (stats != NULL) {
        stats->macroblocks = mbw * mbh;
        stats->tokens = at;
    }
    return 0;
}
